BEGIN;
CREATE TABLE IF NOT EXISTS dance_tenants(id UUID PRIMARY KEY,name TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS dance_tenant_memberships(tenant_id UUID NOT NULL REFERENCES dance_tenants(id),user_id INTEGER NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN('manager','registrar','teacher','finance','guardian_support','auditor','admin')),active BOOLEAN NOT NULL DEFAULT true,PRIMARY KEY(tenant_id,user_id));
CREATE TABLE IF NOT EXISTS dance_guardians(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES dance_tenants(id),external_ref TEXT NOT NULL,name_encrypted TEXT NOT NULL,contact_encrypted TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,external_ref));
CREATE TABLE IF NOT EXISTS dance_students(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES dance_tenants(id),external_ref TEXT NOT NULL,is_minor BOOLEAN NOT NULL,display_name_encrypted TEXT NOT NULL,date_of_birth_encrypted TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,external_ref));
CREATE TABLE IF NOT EXISTS dance_consents(id BIGSERIAL PRIMARY KEY,student_id BIGINT NOT NULL REFERENCES dance_students(id),guardian_id BIGINT NOT NULL REFERENCES dance_guardians(id),purpose TEXT NOT NULL CHECK(purpose IN('program_participation','medical','media_photo','media_video','messaging')),status TEXT NOT NULL CHECK(status IN('granted','revoked')),policy_version TEXT NOT NULL,evidence_hash CHAR(64) NOT NULL,granted_at TIMESTAMPTZ NOT NULL,expires_at TIMESTAMPTZ NOT NULL,revoked_at TIMESTAMPTZ,UNIQUE(student_id,guardian_id,purpose,policy_version));
CREATE TABLE IF NOT EXISTS dance_sections(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES dance_tenants(id),program_name TEXT NOT NULL,teacher_ref TEXT NOT NULL,room_ref TEXT NOT NULL,starts_at TIMESTAMPTZ NOT NULL,ends_at TIMESTAMPTZ NOT NULL,term_starts_at TIMESTAMPTZ NOT NULL,term_ends_at TIMESTAMPTZ NOT NULL,capacity INTEGER NOT NULL CHECK(capacity>0),term_amount_cents INTEGER NOT NULL CHECK(term_amount_cents>=0),version INTEGER NOT NULL DEFAULT 0,CHECK(ends_at>starts_at),CHECK(term_ends_at>term_starts_at));
CREATE TABLE IF NOT EXISTS dance_enrollments(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES dance_tenants(id),student_id BIGINT NOT NULL REFERENCES dance_students(id),section_id BIGINT NOT NULL REFERENCES dance_sections(id),status TEXT NOT NULL CHECK(status IN('requested','active','waitlisted','blocked','completed','dropped','cancelled')),status_reason TEXT,waitlist_position INTEGER,tuition_cents INTEGER NOT NULL CHECK(tuition_cents>=0),idempotency_key TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 0,created_by INTEGER NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key),UNIQUE(student_id,section_id));
CREATE UNIQUE INDEX IF NOT EXISTS dance_waitlist_position_idx ON dance_enrollments(section_id,waitlist_position)WHERE status='waitlisted';
CREATE TABLE IF NOT EXISTS dance_attendance_events(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES dance_tenants(id),enrollment_id BIGINT NOT NULL REFERENCES dance_enrollments(id),session_at TIMESTAMPTZ NOT NULL,status TEXT NOT NULL CHECK(status IN('present','absent','late','excused','makeup')),recorded_by INTEGER NOT NULL REFERENCES users(id),source TEXT NOT NULL,idempotency_key TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS dance_ledger_entries(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES dance_tenants(id),family_ref TEXT NOT NULL,enrollment_id BIGINT REFERENCES dance_enrollments(id),entry_type TEXT NOT NULL CHECK(entry_type IN('charge','payment','credit','refund','proration')),amount_cents INTEGER NOT NULL,currency CHAR(3) NOT NULL DEFAULT'USD',external_payment_ref TEXT,policy_version TEXT NOT NULL,idempotency_key TEXT NOT NULL,reconciled_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS dance_provider_syncs(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES dance_tenants(id),provider TEXT NOT NULL,cursor TEXT,status TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,failure_code TEXT,failure_detail TEXT,started_at TIMESTAMPTZ,completed_at TIMESTAMPTZ,UNIQUE(tenant_id,provider,cursor));
CREATE TABLE IF NOT EXISTS dance_audit_events(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES dance_tenants(id),aggregate_type TEXT NOT NULL,aggregate_id BIGINT NOT NULL,actor_id INTEGER REFERENCES users(id),action TEXT NOT NULL,payload JSONB NOT NULL,occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
COMMIT;
